from typing import List


def max_1122_subarray_length(n: int, a: List[int]) -> int:
    """ Longest contiguous subarray forming a 1122 sequence."""
    best = 0
    for p in (0, 1):
        last = {}
        start = 0
        j = 0
        i = p
        while i + 1 < n:
            if a[i] != a[i + 1]:
                start = j + 1
            else:
                v = a[i]
                if v in last and last[v] + 1 > start:
                    start = last[v] + 1
                last[v] = j
                if j - start + 1 > best:
                    best = j - start + 1
            j += 1
            i += 2
    return best * 2

def count_powerful_integers(start: int, finish: int, limit: int, s: str) -> int:
    """ Count the number of powerful integers in the range [start, finish]."""
    if any(int(c) > limit for c in s):
        return 0
    sv = int(s)
    k = 10 ** len(s)

    def count_le(m):
        # count integers p in [0, m] with all digits <= limit
        if m < 0:
            return 0
        d = str(m)
        n = len(d)
        total = 0
        for i, c in enumerate(d):
            c = int(c)
            # choose digit smaller than c at position i (<= limit)
            total += min(c, limit + 1) * (limit + 1) ** (n - i - 1)
            if c > limit:
                return total
        return total + 1

    def f(n):
        if n < sv:
            return 0
        return count_le((n - sv) // k)

    return f(finish) - f(start - 1)

from typing import List


def max_product_subsequence(nums: List[int], k: int, limit: int) -> int:
    """ Find a non-empty subsequence of nums with alternating sum k that maximizes
    the product without exceeding limit. Returns -1 if none exists.

    >>> max_product_subsequence([1, 2, 3], 2, 10)
    6
    >>> max_product_subsequence([0, 2, 3], -5, 12)
    -1
    >>> max_product_subsequence([2, 2, 3, 3], 0, 9)
    9
    """
    total = sum(nums)
    if abs(k) > total:
        return -1
    OFF = total
    over = limit + 1
    # dp[(parity, prod)] -> bitmask of reachable sums (bit s+OFF), non-empty subsequences
    dp = {}
    for x in nums:
        new = dict(dp)

        def add(key, mask):
            new[key] = new.get(key, 0) | mask

        for (par, p), mask in dp.items():
            if x == 0:
                np_ = 0
            elif p == over:
                np_ = over
            else:
                np_ = p * x
                if np_ > limit:
                    np_ = over
            if par == 0:
                nm = mask << x
            else:
                nm = mask >> x
            if nm:
                add((1 - par, np_), nm)
        # start a new subsequence
        sp = x if x <= limit else over
        add((1, sp), 1 << (OFF + x))
        dp = new
    best = -1
    bit = 1 << (k + OFF)
    for (par, p), mask in dp.items():
        if p <= limit and p > best and mask & bit:
            best = p
    return best

from typing import List

MOD = 998244353


def count_strings_by_lcs_length(n: int, m: int, s: str) -> List[int]:
    """ Count strings of length m by LCS length with s (mod 998244353)."""
    letters = sorted(set(s))
    choices = [(c, 1) for c in letters]
    other = 26 - len(letters)
    if other > 0:
        choices.append(('#', other))

    def step(mask, c):
        row = [0] * (n + 1)
        for j in range(n):
            row[j + 1] = row[j] + ((mask >> j) & 1)
        new = [0] * (n + 1)
        for j in range(1, n + 1):
            if s[j - 1] == c:
                new[j] = row[j - 1] + 1
            else:
                new[j] = max(new[j - 1], row[j])
        nm = 0
        for j in range(n):
            if new[j + 1] - new[j]:
                nm |= 1 << j
        return nm

    trans = {}
    dp = {0: 1}
    for _ in range(m):
        nd = {}
        for mask, v in dp.items():
            if mask not in trans:
                trans[mask] = [(step(mask, c), w) for c, w in choices]
            for nm, w in trans[mask]:
                nd[nm] = (nd.get(nm, 0) + v * w) % MOD
        dp = nd
    res = [0] * (n + 1)
    for mask, v in dp.items():
        k = bin(mask).count('1')
        res[k] = (res[k] + v) % MOD
    return res

from fractions import Fraction
from math import floor


def _black(x, y):
    return (floor(x) + floor(y / 2) + floor((x + y) / 2)) % 2 == 0


def _H(r, s):
    # doubled black area in [0,r]x[0,s], r<=4, s<=2
    tot = 0
    for i in range(r):
        for j in range(s):
            if (i + j) % 2 == 0:
                tot += 2 if _black(Fraction(2 * i + 1, 2), Fraction(2 * j + 1, 2)) else 0
            else:
                # split along x+y=i+j+1 into two triangles of area 1/2 (doubled 1)
                if _black(i + Fraction(1, 4), j + Fraction(1, 4)):
                    tot += 1
                if _black(i + Fraction(3, 4), j + Fraction(3, 4)):
                    tot += 1
    return tot


def _G(x, y):
    a, r = divmod(x, 4)
    b, s = divmod(y, 2)
    return 8 * a * b + a * _H(4, s) + b * _H(r, 2) + _H(r, s)


def calculate_black_area_doubled(A: int, B: int, C: int, D: int) -> int:
    """Twice the black area inside rectangle (A,B)-(C,D)."""
    sx = (-A // 4 + 1) * 4 if A < 0 else 0
    sy = (-B // 2 + 1) * 2 if B < 0 else 0
    A, C = A + sx, C + sx
    B, D = B + sy, D + sy
    return _G(C, D) - _G(A, D) - _G(C, B) + _G(A, B)

from typing import List


def min_ng_list_size(n: int, product_names: List[str]) -> int:
    """Minimum number of strings (walks) covering all product-name edges.

    Letters are nodes, names are directed edges. Edges within a strongly connected
    component can all be covered by a single walk through it, so each such component
    is one item; other edges are items on their own. Walks may reuse items, so the
    answer is a minimum chain cover (Dilworth) of the reachability order on items.
    """
    N = 26
    reach = [[i == j for j in range(N)] for i in range(N)]
    edges = []
    for s in set(product_names):
        u, v = ord(s[0]) - 65, ord(s[1]) - 65
        edges.append((u, v))
        reach[u][v] = True
    for k in range(N):
        rk = reach[k]
        for i in range(N):
            if reach[i][k]:
                ri = reach[i]
                for j in range(N):
                    if rk[j]:
                        ri[j] = True

    def comp(x):
        return min(y for y in range(N) if reach[x][y] and reach[y][x])

    items = set()
    for u, v in edges:
        cu, cv = comp(u), comp(v)
        if cu == cv:
            items.add(("S", cu, cu))
        else:
            items.add(("E", u, v))
    items = list(items)
    m = len(items)
    # (tail node, head node) for reachability
    th = [(a[1], a[2]) for a in items]
    adj = [[] for _ in range(m)]
    for i in range(m):
        for j in range(m):
            if i != j and reach[th[i][1]][th[j][0]]:
                adj[i].append(j)

    match = [-1] * m

    def try_(u, seen):
        for v in adj[u]:
            if not seen[v]:
                seen[v] = True
                if match[v] < 0 or try_(match[v], seen):
                    match[v] = u
                    return True
        return False

    import sys
    sys.setrecursionlimit(10000)
    cnt = 0
    for i in range(m):
        if try_(i, [False] * m):
            cnt += 1
    return m - cnt

import sys


def count_paths(H: int, W: int, K: int, grid: list[str]) -> int:
    """Count self-avoiding paths with K moves over empty cells."""
    sys.setrecursionlimit(10000)
    nbrs = [[] for _ in range(H * W)]
    for r in range(H):
        for c in range(W):
            if grid[r][c] != '.':
                continue
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                nr, nc = r + dr, c + dc
                if 0 <= nr < H and 0 <= nc < W and grid[nr][nc] == '.':
                    nbrs[r * W + c].append(nr * W + nc)

    def dfs(v, mask, left):
        if left == 0:
            return 1
        total = 0
        for u in nbrs[v]:
            b = 1 << u
            if not mask & b:
                total += dfs(u, mask | b, left - 1)
        return total

    ans = 0
    for r in range(H):
        for c in range(W):
            if grid[r][c] == '.':
                v = r * W + c
                ans += dfs(v, 1 << v, K)
    return ans

from functools import lru_cache


@lru_cache(maxsize=None)
def _g(rem, s, p):
    # p nonzero product so far; count completions of length rem that are beautiful
    if rem == 0:
        return 1 if p % s == 0 else 0
    total = 10 ** (rem - 1)  # digit 0 -> product zero -> always beautiful
    for d in range(1, 10):
        total += _g(rem - 1, s + d, p * d)
    return total


def _f(n):
    if n <= 0:
        return 0
    ds = [int(c) for c in str(n)]
    L = len(ds)
    total = 0
    for m in range(1, L):
        for d in range(1, 10):
            total += _g(m - 1, d, d)
    s, p = 0, 1
    for i, dig in enumerate(ds):
        rem = L - i - 1
        for d in range(1 if i == 0 else 0, dig):
            if d == 0:
                total += 10 ** rem
            else:
                total += _g(rem, s + d, p * d)
        if dig == 0:
            rest = int("".join(map(str, ds[i + 1:])) or "0")
            return total + rest + 1
        s += dig
        p *= dig
    if p % s == 0:
        total += 1
    return total


def count_beautiful_numbers(l: int, r: int) -> int:
    """Count beautiful numbers in [l, r] (product of digits divisible by digit sum)."""
    return _f(r) - _f(l - 1)

from itertools import product
from math import factorial


def count_k_palindromic_numbers(n: int, k: int) -> int:
    """ Count good integers with exactly n digits (rearrangeable to a k-palindromic integer)."""
    h = (n + 1) // 2
    seen = set()
    for first in range(1, 10):
        for rest in product(range(10), repeat=h - 1):
            half = (first,) + rest
            s = "".join(map(str, half))
            full = s + (s[::-1] if n % 2 == 0 else s[:-1][::-1])
            if int(full) % k == 0:
                cnt = [0] * 10
                for ch in full:
                    cnt[int(ch)] += 1
                seen.add(tuple(cnt))
    total = 0
    for cnt in seen:
        denom = 1
        for c in cnt:
            denom *= factorial(c)
        perms = factorial(n) // denom
        if cnt[0] > 0:
            perms -= factorial(n - 1) // (denom // cnt[0])
        total += perms
    return total

from typing import List, Tuple
from collections import deque


def _maxflow(N, adj_edges, s, t, limit):
    graph = [[] for _ in range(N)]
    to = []
    cap = []
    for a, b, c in adj_edges:
        graph[a].append(len(to)); to.append(b); cap.append(c)
        graph[b].append(len(to)); to.append(a); cap.append(0)
    flow = 0
    while flow <= limit:
        prev = [-1] * N
        prev[s] = -2
        dq = deque([s])
        while dq and prev[t] == -1:
            x = dq.popleft()
            for e in graph[x]:
                if cap[e] > 0 and prev[to[e]] == -1:
                    prev[to[e]] = e
                    dq.append(to[e])
        if prev[t] == -1:
            break
        # bottleneck
        f = float('inf')
        x = t
        while x != s:
            e = prev[x]
            f = min(f, cap[e])
            x = to[e ^ 1]
        x = t
        while x != s:
            e = prev[x]
            cap[e] -= f
            cap[e ^ 1] += f
            x = to[e ^ 1]
        flow += f
        if f == float('inf'):
            return float('inf')
    return flow


def max_shortest_distance(n: int, m: int, k: int, edges: List[Tuple[int, int]]) -> int:
    """ Given a directed graph with n vertices (numbered 1 to n) and m edges, where initially
    all edges have weight 0. You can choose exactly k edges and change their weights to 1.
    Find the maximum possible shortest distance from vertex 1 to vertex n after this operation.
    """
    INF = 10 ** 9
    best = 0
    for d in range(1, n):
        # node (v, i): v in 0..n-1, i in 1..d  -> v*d + (i-1)
        S = n * d
        T = S + 1
        N = T + 1

        def node(v, i):
            return v * d + (i - 1)

        es = []
        for v in range(n):
            for i in range(1, d):
                es.append((node(v, i + 1), node(v, i), INF))
        for i in range(1, d + 1):
            es.append((S, node(n - 1, i), INF))
            es.append((node(0, i), T, INF))
        for (u, v) in edges:
            u -= 1
            v -= 1
            for i in range(1, d + 1):
                es.append((node(v, i), node(u, i), 1))
                if i + 1 <= d:
                    es.append((node(v, i + 1), node(u, i), INF))
        if _maxflow(N, es, S, T, k) <= k:
            best = d
    return best

def count_good_string_replacements(n: int, k: int, s: str) -> int:
    """ Count replacements of '?' so that the string has at least k good substrings.
    A substring is good iff parities of counts of A, B, C are all equal.
    """
    MOD = 998244353
    flips = {'A': 2, 'B': 3, 'C': 1}
    dp = {((1, 0, 0, 0), 0): 1}
    for ch in s:
        opts = [flips[ch]] if ch in flips else [1, 2, 3]
        nd = {}
        for (cnt, cur), v in dp.items():
            for f in opts:
                ns = cur ^ f
                l = list(cnt)
                l[ns] += 1
                key = (tuple(l), ns)
                nd[key] = (nd.get(key, 0) + v) % MOD
        dp = nd
    total = 0
    for (cnt, cur), v in dp.items():
        pairs = sum(c * (c - 1) // 2 for c in cnt)
        if pairs >= k:
            total = (total + v) % MOD
    return total

from math import gcd
from typing import List


def kth_smallest_amount(coins: List[int], k: int) -> int:
    """ Return the k-th smallest amount that is a multiple of at least one coin.

    >>> kth_smallest_amount([3, 6, 9], 3)
    9
    >>> kth_smallest_amount([5, 2], 7)
    12
    """
    coins = sorted(set(coins))
    reduced = []
    for c in coins:
        if not any(c % r == 0 for r in reduced):
            reduced.append(c)
    coins = reduced
    hi = min(coins) * k
    coef = {}
    lcms = [(1, -1)]  # (lcm, sign) with empty set sign -1
    for c in coins:
        new = []
        for l, s in lcms:
            nl = l * c // gcd(l, c)
            if nl <= hi:
                new.append((nl, -s))
        lcms.extend(new)
    for l, s in lcms[1:]:
        coef[l] = coef.get(l, 0) + s
    items = [(l, s) for l, s in coef.items() if s]

    def count(x):
        return sum(s * (x // l) for l, s in items)

    lo = 1
    while lo < hi:
        mid = (lo + hi) // 2
        if count(mid) >= k:
            hi = mid
        else:
            lo = mid + 1
    return lo
